      "tiers": [
        {
          "id": "volume.weighted_sets:t1",
          "title": "Первый взмах палочки",
          "phrase": "Ты записал 10 подходов с сохранённым весом больше нуля. В железном оркестре первая гантель уже ждёт взмаха палочки.",
          "imagePrompt": "A little robot conductor on spring legs raises a baton toward a single animated dumbbell beside a small drum. The dumbbell grips two drumsticks with flexible metal arms, waiting attentively as the robot gives an encouraging nod.",
          "fishMarkup": "[warm] Ты записал 10 подходов с сохранённым весом больше нуля. [playful] В железном оркестре первая гантель уже ждёт взмаха палочки.",
          "audioText": "Ты записал 10 подходов с сохранённым весом больше нуля. В железном оркестре первая гантель уже ждёт взмаха палочки."
        },
        {
          "id": "volume.weighted_sets:t2",
          "title": "Железо вступает хором",
          "phrase": "В твоём журнале уже 50 подходов с сохранённым весом больше нуля. Железный оркестр разросся: у каждой гантели своя партия.",
          "imagePrompt": "A little robot conductor on spring legs directs a semicircle of animated dumbbells playing drums, cymbals and a xylophone. Its baton sweeps sideways while the dumbbell musicians lean into their instruments in coordinated rows.",
          "fishMarkup": "[confident] В твоём журнале уже 50 подходов с сохранённым весом больше нуля. [playful] Железный оркестр разросся: у каждой гантели своя партия.",
          "audioText": "В твоём журнале уже 50 подходов с сохранённым весом больше нуля. Железный оркестр разросся: у каждой гантели своя партия."
        },
        {
          "id": "volume.weighted_sets:t3",
          "title": "Аплодисменты тяжёлого состава",
          "phrase": "За всё время у тебя набралось 150 подходов с сохранённым весом больше нуля. Железный оркестр аплодирует — гантели хлопают блинами.",
          "imagePrompt": "A little robot conductor on spring legs takes a deep bow on a podium. Around it, an orchestra of animated dumbbells applauds by clapping detached weight plates together, while the robot holds a comically tiny dumbbell as its baton.",
          "fishMarkup": "[triumphant] За всё время у тебя набралось 150 подходов с сохранённым весом больше нуля. [playful] Железный оркестр аплодирует — <slow>гантели хлопают блинами.</slow>",
          "audioText": "За всё время у тебя набралось 150 подходов с сохранённым весом больше нуля. Железный оркестр аплодирует — гантели хлопают блинами."
        }
      ]
